pub mod commands;
pub mod state;

use specta_typescript::Typescript;
use tauri_specta::{Builder, collect_commands};
use tracing_subscriber::EnvFilter;

use crate::state::AppState;

pub fn specta_builder() -> Builder<tauri::Wry> {
    Builder::<tauri::Wry>::new().commands(collect_commands![
        commands::get_workspace_overview,
        commands::update_settings,
        commands::reset_nextcloud_url,
    ])
}

pub fn typescript_exporter() -> Typescript {
    Typescript::default().header(
        "// This file is auto-generated by tauri-specta. Do not edit manually.\n// Run `cargo test -p fr-desktop export_bindings` to regenerate.",
    )
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    let _ = tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .try_init();

    let builder = specta_builder();

    #[cfg(debug_assertions)]
    {
        let bindings_path =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../ui/src/bindings/tauri.ts");
        if let Err(err) = builder.export(typescript_exporter(), &bindings_path) {
            tracing::warn!("Failed to export TypeScript IPC bindings: {err}");
        }
    }

    let app_state = AppState::initialize();

    tauri::Builder::default()
        .plugin(tauri_plugin_opener::init())
        .manage(app_state)
        .invoke_handler(builder.invoke_handler())
        .setup(move |app| {
            builder.mount_events(app);
            Ok(())
        })
        .run(tauri::generate_context!())
        .expect("error while running FR Universal App");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn export_bindings() {
        let bindings_path =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../ui/src/bindings/tauri.ts");
        specta_builder()
            .export(typescript_exporter(), &bindings_path)
            .expect("Failed to export TypeScript bindings");
    }
}
